WITH supplier_stats AS (SELECT supplier_id, SUM(cost) total_cost, COUNT(DISTINCT cost) unique_brands FROM products WHERE price <= 300 GROUP BY supplier_id) SELECT suppliers.id, suppliers.supplier_name, suppliers.city, supplier_stats.total_cost, supplier_stats.unique_brands FROM suppliers INNER JOIN supplier_stats ON suppliers.id = supplier_stats.supplier_id WHERE supplier_stats.unique_brands > 6 ORDER BY supplier_stats.total_cost DESC;
